import{_ as a,o as t,c as s,a2 as i}from"./chunks/framework.7R1OEGYz.js";const k=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"troubleshooting.md","filePath":"troubleshooting.md","lastUpdated":null}'),n={name:"troubleshooting.md"};function r(h,e,o,l,d,p){return t(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><h2 id="helm" tabindex="-1">Helm <a class="header-anchor" href="#helm" aria-label="Permalink to &quot;Helm&quot;">​</a></h2><h3 id="nil-pointer-evaluating-interface-enabled" tabindex="-1"><code>nil pointer evaluating interface {}.enabled</code> <a class="header-anchor" href="#nil-pointer-evaluating-interface-enabled" aria-label="Permalink to &quot;`nil pointer evaluating interface {}.enabled`&quot;">​</a></h3><p>An upgrade with <code>--reuse-values</code> did not pick up a chart key that was added after your release was installed. Use <code>--reset-then-reuse-values</code>, or keep a values file and pass it with <code>-f</code>. Full explanation in <a href="/docs/upgrading">Upgrading</a>.</p><h3 id="chat-telegram-chat-signal-require-backend-replicas-1" tabindex="-1"><code>chat.telegram/chat.signal require backend.replicas=1</code> <a class="header-anchor" href="#chat-telegram-chat-signal-require-backend-replicas-1" aria-label="Permalink to &quot;`chat.telegram/chat.signal require backend.replicas=1`&quot;">​</a></h3><p>Working as intended — see <a href="/docs/chat#one-replica-only">one replica only</a>. Add <code>--set backend.replicas=1</code>.</p><h2 id="telegram" tabindex="-1">Telegram <a class="header-anchor" href="#telegram" aria-label="Permalink to &quot;Telegram&quot;">​</a></h2><h3 id="nothing-arrives-and-the-log-looks-fine" tabindex="-1">Nothing arrives, and the log looks fine <a class="header-anchor" href="#nothing-arrives-and-the-log-looks-fine" aria-label="Permalink to &quot;Nothing arrives, and the log looks fine&quot;">​</a></h3><p>The backend logs nothing on success, so silence is not evidence of anything. Query the bot directly:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;https://api.telegram.org/bot&lt;token&gt;/getMyCommands&quot;</span></span></code></pre></div><p>An empty <code>result</code> means the backend never reached Telegram. See <a href="/docs/chat#verify-telegram">verifying Telegram</a>.</p><h3 id="telegram-long-polling-not-started-no-bot-token-disabled" tabindex="-1"><code>Telegram long polling not started (no bot token / disabled)</code> <a class="header-anchor" href="#telegram-long-polling-not-started-no-bot-token-disabled" aria-label="Permalink to &quot;`Telegram long polling not started (no bot token / disabled)`&quot;">​</a></h3><p>The configuration did not reach the pod. Check both:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agenthub</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agenthub-config</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> yaml</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Telegram</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agenthub</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> secret</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agenthub-secrets</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> jsonpath=&#39;{.data}&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Telegram</span></span></code></pre></div><p>If the ConfigMap has no <code>Chat__Telegram__*</code> keys at all, your deployed chart revision predates the chat integration — upgrade the chart, not just the values.</p><h3 id="conflict-terminated-by-other-getupdates-request" tabindex="-1"><code>Conflict: terminated by other getUpdates request</code> <a class="header-anchor" href="#conflict-terminated-by-other-getupdates-request" aria-label="Permalink to &quot;`Conflict: terminated by other getUpdates request`&quot;">​</a></h3><p>Two pollers are talking to the same bot. For a few seconds during a rolling update this is normal. If it persists, <code>backend.replicas</code> is greater than 1, or a second deployment (a dev cluster, a laptop) is using the same bot token. Use a separate bot per environment.</p><h2 id="git-connections" tabindex="-1">Git connections <a class="header-anchor" href="#git-connections" aria-label="Permalink to &quot;Git connections&quot;">​</a></h2><h3 id="the-connect-buttons-do-not-appear" tabindex="-1">The Connect buttons do not appear <a class="header-anchor" href="#the-connect-buttons-do-not-appear" aria-label="Permalink to &quot;The Connect buttons do not appear&quot;">​</a></h3><p>The UI shows them only when at least one provider has a client id <em>and</em> a secret. Check:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">your-hos</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/api/config</span></span></code></pre></div><p><code>&quot;gitEnabled&quot;: true</code> means the backend sees a usable provider.</p><h3 id="oauth-breaks-after-every-restart" tabindex="-1">OAuth breaks after every restart <a class="header-anchor" href="#oauth-breaks-after-every-restart" aria-label="Permalink to &quot;OAuth breaks after every restart&quot;">​</a></h3><p><code>git.stateKey</code> is unset, so a random key is generated at startup and the signed state from before the restart no longer validates. Set a fixed random string of 32+ characters.</p><h3 id="redirect-uri-mismatch-at-the-provider" tabindex="-1"><code>redirect_uri</code> mismatch at the provider <a class="header-anchor" href="#redirect-uri-mismatch-at-the-provider" aria-label="Permalink to &quot;`redirect_uri` mismatch at the provider&quot;">​</a></h3><p>The registered URI must match <code>https://&lt;your-host&gt;/api/git/callback/&lt;provider-id&gt;</code> exactly, including the provider id from your values file. Also make sure you did not register the OIDC login callback (<code>/auth/callback</code>) by mistake — see <a href="/docs/git">Git integrations</a>.</p><h2 id="sessions" tabindex="-1">Sessions <a class="header-anchor" href="#sessions" aria-label="Permalink to &quot;Sessions&quot;">​</a></h2><h3 id="the-agent-is-stuck-waiting-on-a-permission-prompt" tabindex="-1">The agent is stuck waiting on a permission prompt <a class="header-anchor" href="#the-agent-is-stuck-waiting-on-a-permission-prompt" aria-label="Permalink to &quot;The agent is stuck waiting on a permission prompt&quot;">​</a></h3><p>Prompts expire after about 30 minutes. Answer in the web terminal, in your messenger, or switch on <a href="/docs/auto-approve">auto approve</a> — enabling it also resolves the prompts that are already pending.</p><h2 id="reading-the-logs" tabindex="-1">Reading the logs <a class="header-anchor" href="#reading-the-logs" aria-label="Permalink to &quot;Reading the logs&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agenthub</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy/agenthub-backend</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --tail=200</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agenthub</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy/agenthub-backend</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --since=5m</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> telegram</span></span></code></pre></div><p>Bot tokens and client secrets are kept out of these logs deliberately. If you ever see a credential in there, that is a bug worth reporting.</p>',32)])])}const g=a(n,[["render",r]]);export{k as __pageData,g as default};
